  values(v_release_id, 11, 'g11_st2', 1, 2, 'match', 'Nối khái niệm với đặc điểm', 'Nêu khái niệm cảm ứng và các giai đoạn đáp ứng kích thích.', '{"leftItems":["Kích thích","Thụ thể","Đáp ứng"],"rightItems":["Phản ứng của cơ thể","Tiếp nhận kích thích","Thay đổi từ môi trường"],"hint":"“Kích thích” tương ứng với “Thay đổi từ môi trường”."}'::jsonb, '{"value":[{"left":"Kích thích","right":"Thay đổi từ môi trường"},{"left":"Thụ thể","right":"Tiếp nhận kích thích"},{"left":"Đáp ứng","right":"Phản ứng của cơ thể"}],"explanation":"Kích thích: Thay đổi từ môi trường; Thụ thể: Tiếp nhận kích thích; Đáp ứng: Phản ứng của cơ thể."}'::jsonb, '[{"source":"SGK Sinh học 11 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 14. Khái quát về cảm ứng ở sinh vật"}]'::jsonb);
